import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { batchPriceListPricesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await batchPriceListPricesWorkflow(req.scope)
    .run({
      input: {
        data: {
          id: "plist_123",
          create: [{
            amount: 10,
            currency_code: "usd",
            variant_id: "variant_123"
          }],
          update: [{
            id: "price_123",
            amount: 10,
            currency_code: "usd",
            variant_id: "variant_123"
          }],
          delete: ["price_321"]
        }
      }
    })

  res.send(result)
}

